__global__ void derivative_y(float *f, float *df)
{
  __shared__ float s_f[Y_TILE + 8][lPencils];

  int tx = threadIdx.x;
  int ty = threadIdx.y;
  int i = blockIdx.x * blockDim.x + tx;
  int k = blockIdx.z;
  int yBase = blockIdx.y * Y_TILE;
  int planeOffset = k * mx * my;

  // Each thread loads two rows; together the block initializes all tile rows,
  // including the four-row halos on both sides.
  int q0 = yBase + ty - 4;
  int q1 = yBase + ty + Y_TILE - 4;
  if (q0 < 0) q0 += my - 1;
  else if (q0 > my - 1) q0 -= my - 1;
  if (q1 < 0) q1 += my - 1;
  else if (q1 > my - 1) q1 -= my - 1;

  s_f[ty][tx] = f[planeOffset + q0 * mx + i];
