__global__ void derivative_y(float *f, float *df)
{
  __shared__ float s_f[Y_TILE + 8][lPencils];

  int tx = threadIdx.x;
  int ty = threadIdx.y;
  int i = blockIdx.x * blockDim.x + tx;
  int k = blockIdx.z;
  int yBase = blockIdx.y * Y_TILE;
  int planeOffset = k * mx * my;

  // Each thread loads two rows; together the block initializes all tile rows,
  // including the four-row halos on both sides.
  int q0 = yBase + ty - 4;
  int q1 = yBase + ty + Y_TILE - 4;
  if (q0 < 0) q0 += my - 1;
  else if (q0 > my - 1) q0 -= my - 1;
  if (q1 < 0) q1 += my - 1;
  else if (q1 > my - 1) q1 -= my - 1;

  s_f[ty][tx] = f[planeOffset + q0 * mx + i];
  s_f[ty + Y_TILE][tx] = f[planeOffset + q1 * mx + i];
  __syncthreads();

  int sj = ty + 4;
  int globalIdx = planeOffset + (yBase + ty) * mx + i;

  df[globalIdx] =
    ( c_ay * ( s_f[sj+1][tx] - s_f[sj-1][tx] )
    + c_by * ( s_f[sj+2][tx] - s_f[sj-2][tx] )
    + c_cy * ( s_f[sj+3][tx] - s_f[sj-3][tx] )
    + c_dy * ( s_f[sj+4][tx] - s_f[sj-4][tx] ) );
}

extern "C" void run(const float*A, const float*B, float*C, float*scratch,
                     int n, int m, int k, float alpha, float beta)
{
  static bool initialized = false;
  if (!initialized) {
    setDerivativeParameters();
    initialized = true;
  }
  derivative_y<<<grid[1][1], block[1][1]>>>((float*)A, C);
}

