// Each lane owns one X coordinate and computes two consecutive Y outputs.
// The nine-value rolling window is shifted once to produce the second output.
__global__ void derivative_y_two_outputs(const float *f, float *df)
{
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  const int y = (blockIdx.y * blockDim.y + threadIdx.y) * 2;
  const int k = blockIdx.z;

  float v0 = load_y_sample(f, i, k, y - 4);
  float v1 = load_y_sample(f, i, k, y - 3);
  float v2 = load_y_sample(f, i, k, y - 2);
  float v3 = load_y_sample(f, i, k, y - 1);
  float v4 = load_y_sample(f, i, k, y);
  float v5 = load_y_sample(f, i, k, y + 1);
  float v6 = load_y_sample(f, i, k, y + 2);
  float v7 = load_y_sample(f, i, k, y + 3);
  float v8 = load_y_sample(f, i, k, y + 4);

  const float out0 =
    ( c_ay * (v5 - v3)
    + c_by * (v6 - v2)
    + c_cy * (v7 - v1)
    + c_dy * (v8 - v0) );

  const float entering = load_y_sample(f, i, k, y + 5);
  v0 = v1;
  v1 = v2;
  v2 = v3;
  v3 = v4;
  v4 = v5;
  v5 = v6;
  v6 = v7;
  v7 = v8;
  v8 = entering;

  const float out1 =
    ( c_ay * (v5 - v3)
    + c_by * (v6 - v2)
    + c_cy * (v7 - v1)
    + c_dy * (v8 - v0) );

  const int output = (k * my + y) * mx + i;
  df[output] = out0;
  df[output + mx] = out1;
}

extern "C" void run(const float *A, const float *B, float *C, float *scratch,
                    int n, int m, int k, float alpha, float beta)
{
  static bool initialized = false;
  if (!initialized) {
    setDerivativeParameters();
    initialized = true;
  }

  const dim3 rowBlock(32, 4, 1);
  const dim3 rowGrid(mx / rowBlock.x, my / (2 * rowBlock.y), mz);
  derivative_y_two_outputs<<<rowGrid, rowBlock>>>(A, C);
}

